import{_ as s,o as n,a as p,b as t}from"./app.C41L12d5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"原型注册与管理","link":"/api/Utils-API/prototype_register_management/prototype_register_management"},{"text":"OpAICoreConfig","link":"/api/Utils-API/prototype_register_management/OpAICoreConfig/OpAICoreConfig"},{"text":"ExtendCfgInfo","link":"/api/Utils-API/prototype_register_management/OpAICoreConfig/ExtendCfgInfo"}]},"headers":[],"relativePath":"api/Utils-API/prototype_register_management/OpAICoreConfig/ExtendCfgInfo.md","filePath":"api/Utils-API/prototype_register_management/OpAICoreConfig/ExtendCfgInfo.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1785997882000}'),c={name:"api/Utils-API/prototype_register_management/OpAICoreConfig/ExtendCfgInfo.md"};function l(e,a,o,i,r,h){return n(),p("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>ExtendCfgInfo<span id="ZH-CN_TOPIC_0000002114097093"></span></h1><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000001600884192_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section36583473819"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>用于扩展算子相关参数配置，提供更灵活的参数配置能力。</p><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000001600884192_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section13230182415108"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>OpAICoreConfig &amp;OpAICoreConfig::ExtendCfgInfo(const char *key, const char *value)
</code></pre></div><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000001600884192_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section75395119104"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">key</td><td align="left">配置项，如&quot;aclnnSupport.value&quot;。</td></tr><tr><td align="left">value</td><td align="left">配置项key对应的取值，如&quot;aclnnSupport.value&quot;，可以填充&quot;support_aclnn&quot;或者&quot;aclnn_only&quot;。</td></tr></tbody></table><p>ExtendCfgInfo支持的参数如下表：</p><p><strong>表2</strong> ExtendCfgInfo支持配置的参数</p><table><thead><tr><th align="left">参数名</th><th align="left">功能介绍</th></tr></thead><tbody><tr><td align="left">aclnnSupport.value</td><td align="left">- support_aclnn：此模式下，静态Shape场景中该算子通过模型下沉执行，动态Shape场景则在Host侧调用fallback函数下发算子。如果调用了<a href="../OpDef/EnableFallBack.html">EnableFallBack</a>则默认采用该模式。<br>- aclnn_only：此模式下，动静态Shape场景中该算子均以fallback形式下发。不建议用户使用该模式，后续版本待废弃。<br>关于fallback下发算子的详细介绍请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityGraphguide">《图引擎开发指南》</a>。</td></tr></tbody></table><p>support_aclnn使用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 如下为动态Shape场景的示例</span>
<span class="n">OpAICoreConfig</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">;</span>
<span class="n">aicore_config</span><span class="p">.</span><span class="n">DynamicShapeSupportFlag</span><span class="p">(</span><span class="nb">true</span><span class="p">)</span><span class="w">   </span><span class="c1">// 动态Shape场景需要设置DynamicShapeSupportFlag为true</span>
<span class="w">             </span><span class="p">.</span><span class="n">ExtendCfgInfo</span><span class="p">(</span><span class="s">&quot;aclnnSupport.value&quot;</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;support_aclnn&quot;</span><span class="p">);</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">().</span><span class="n">AddConfig</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">);</span>

<span class="c1">// 如下为静态Shape场景的示例</span>
<span class="n">OpAICoreConfig</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">;</span>
<span class="n">aicore_config</span><span class="p">.</span><span class="n">DynamicCompileStaticFlag</span><span class="p">(</span><span class="nb">true</span><span class="p">)</span><span class="w">  </span><span class="c1">// 静态Shape场景需要设置DynamicCompileStaticFlag为true</span>
<span class="w">             </span><span class="p">.</span><span class="n">ExtendCfgInfo</span><span class="p">(</span><span class="s">&quot;aclnnSupport.value&quot;</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;support_aclnn&quot;</span><span class="p">);</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">().</span><span class="n">AddConfig</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">);</span>
</code></pre></div><p>aclnn_only使用示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 如下为动态Shape场景的示例</span>
<span class="n">OpAICoreConfig</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">;</span>
<span class="n">aicore_config</span><span class="p">.</span><span class="n">DynamicShapeSupportFlag</span><span class="p">(</span><span class="nb">true</span><span class="p">)</span><span class="w"> </span><span class="c1">// 动态Shape场景需要设置DynamicShapeSupportFlag为true</span>
<span class="w">			 </span><span class="p">.</span><span class="n">ExtendCfgInfo</span><span class="p">(</span><span class="s">&quot;aclnnSupport.value&quot;</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;aclnn_only&quot;</span><span class="p">);</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">().</span><span class="n">AddConfig</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">);</span>
<span class="c1">// 如下为静态Shape场景的示例</span>
<span class="n">OpAICoreConfig</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">;</span><span class="w">              </span><span class="c1">// 无需配置DynamicCompileStaticFlag/DynamicShapeSupportFlag，算子均以fallback形式下发，即动态Shape模型的下发方式</span>
<span class="n">aicore_config</span><span class="p">.</span><span class="n">ExtendCfgInfo</span><span class="p">(</span><span class="s">&quot;aclnnSupport.value&quot;</span><span class="p">,</span><span class="w"> </span><span class="s">&quot;aclnn_only&quot;</span><span class="p">);</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">().</span><span class="n">AddConfig</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">aicore_config</span><span class="p">);</span>
</code></pre></div><h2 id="返回值说明">返回值说明<span id="zh-cn_topic_0000001600884192_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section25791320141317"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>OpAICoreConfig算子定义，请参考<a href="OpAICoreConfig.html">OpAICoreConfig</a>。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000001600884192_zh-cn_topic_0000001576875005_zh-cn_topic_0000001525424352_section19165124931511"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>无</p></article></div>`,1)])])}const _=s(c,[["render",l]]);export{g as __pageData,_ as default};
